<script setup>
import { computed, ref, watch } from 'vue'
import { useLocalSpeech } from './useLocalSpeech.js'
import { metricLabel, observationSourceLabel, statusLabel, sourceRows } from './presentation.js'
const props=defineProps({report:Object,busy:Boolean,error:String,notice:String})
const emit=defineEmits(['close','export','next-step'])
const {speaking,speechMessage,speak,stop}=useLocalSpeech()
watch(()=>props.report?.id,stop)
const exportOpen=ref(false)
const doc=computed(()=>props.report?.document?.schemaVersion==='agriculture.report.v1'?props.report.document:null)
const time=v=>v?new Date(v*1000).toLocaleString('zh-CN',{timeZone:doc.value?.timezone || 'Asia/Shanghai'}): '未设定'
const groups=computed(()=>{const result=new Map();for(const item of doc.value?.observations||[]){const key=[item.deviceId,item.metric,item.unit,item.source].join('|');if(!result.has(key))result.set(key,{key,metric:item.metric,unit:item.unit,source:item.source,device:item.deviceId,rows:[]});result.get(key).rows.push(item)}return [...result.values()].map(g=>({...g,rows:g.rows.sort((a,b)=>a.observedAt-b.observedAt)}))})
const unitLabel=value=>({celsius:'°C',percent:'%'})[value] || value || '单位未提供'
const metricCount=computed(()=>new Set((doc.value?.observations || []).map(item=>item.metric)).size)
const pendingTasks=computed(()=>(doc.value?.tasks || []).filter(item=>!['completed','cancelled'].includes(item.status)).slice(0,2))
const deviceLabel=group=>{const devices=[...new Set(groups.value.filter(item=>item.source===group.source).map(item=>item.device))];return `${group.source==='demo'?'模拟监测':group.source==='test'?'手工记录':'设备监测'}${devices.indexOf(group.device)+1}`}
function readableLimit(value){return String(value).replace(/(实际覆盖(?:时间：| )?)(\d+(?:\.\d+)?) 至 (\d+(?:\.\d+)?) Unix秒。?/,(_all,prefix,start,end)=>`${prefix}${time(Number(start))} 至 ${time(Number(end))}。`)}
function chart(g){const values=g.rows.map(x=>Number(x.value));const min=Math.min(...values),max=Math.max(...values),span=max-min||1;const start=g.rows[0].observedAt,end=g.rows.at(-1).observedAt;return {min,max,points:g.rows.map(x=>`${45+(end===start?145:(x.observedAt-start)*290/(end-start))},${130-(Number(x.value)-min)/span*95}`).join(' ')}}
</script>
<template><section class="report-document-layer" role="dialog" aria-modal="true" aria-label="园区报告"><header class="report-toolbar"><button @click="emit('close')">← 返回</button><strong>园区报告</strong><button @click="speaking?stop():speak(report.body)">{{ speaking?'停止朗读':'🔊 听简报' }}</button><button :disabled="busy" @click="exportOpen=true">导出 Markdown</button></header><p v-if="error" class="agri-error" role="alert">{{ error }}</p><p v-if="notice" class="agri-notice" role="status">{{ notice }}</p><p v-if="speechMessage" role="status">{{ speechMessage }}</p><article class="report-paper"><h1>{{ report.title }}</h1><p>{{ time(doc?.generatedAt || report.createdAt) }}</p><template v-if="doc"><div class="report-summary report-summary-desktop"><h2>🍃 记录摘要</h2><p>所选任务 {{ doc.summary.taskCount }} 项，已完成 {{ doc.summary.completedTaskCount }} 项；关联现场记录 {{ doc.summary.recordCount }} 条。</p><p v-for="task in pendingTasks" :key="task.id">待跟进：{{ task.title }}</p><small>观察范围：{{ time(doc.period.from) }} — {{ time(doc.period.to) }} · {{ doc.timezone }}</small></div><div class="report-statistics"><div><strong>{{ doc.summary.recordCount }}</strong>现场记录</div><div><strong>{{ doc.summary.completedTaskCount }}</strong>已完成</div><div><strong>{{ doc.photos.length }}</strong>关联照片<small>{{ doc.observations.length }} 条监测记录</small></div></div><h2>现场照片</h2><div class="report-photos"><figure v-for="photo in doc.photos" :key="photo.assetId"><img v-if="photo.available && photo.contentUrl" :src="photo.contentUrl" :alt="photo.name" @error="event=>{event.target.hidden=true;event.target.nextElementSibling.hidden=false}"><p :hidden="photo.available && photo.contentUrl">来源照片不可用</p><figcaption>{{ photo.caption || photo.name }}<small>记录时间：{{ time(photo.recordCompletedAt) }}</small></figcaption></figure></div><p v-if="!doc.photos.length">暂无关联照片</p><div class="report-work-mobile"><h2>本次做了什么</h2><table><thead><tr><th>事项</th><th>截止时间</th><th>状态</th></tr></thead><tbody><tr v-for="task in doc.tasks" :key="task.id"><td>{{ task.title }}</td><td>{{ time(task.dueAt) }}</td><td>{{ statusLabel(task.status) }}</td></tr></tbody></table><p v-if="!doc.tasks.length">未选择任务</p></div><details class="report-summary-mobile"><summary>完整记录摘要与观察范围</summary><div class="report-summary"><h2>🍃 记录摘要</h2><p>所选任务 {{ doc.summary.taskCount }} 项，已完成 {{ doc.summary.completedTaskCount }} 项；关联现场记录 {{ doc.summary.recordCount }} 条。</p><p v-for="task in pendingTasks" :key="task.id">待跟进：{{ task.title }}</p><small>观察范围：{{ time(doc.period.from) }} — {{ time(doc.period.to) }} · {{ doc.timezone }}</small></div></details><details><summary>环境变化与监测依据</summary><p v-if="!groups.length">该时段暂无监测数据</p><div class="report-charts"><figure v-for="group in groups" :key="group.key"><figcaption>{{ metricLabel(group.metric) }} · {{ unitLabel(group.unit) }}<small>{{ observationSourceLabel(group.source) }} · {{ deviceLabel(group) }}</small></figcaption><svg viewBox="0 0 360 175" role="img" :aria-label="`${metricLabel(group.metric)} ${group.rows.length}条记录，单位${unitLabel(group.unit)}`"><path d="M45 25V140H340" fill="none" stroke="#80968b"/><path d="M45 35H335M45 82H335M45 130H335" stroke="#e4ece7"/><text x="2" y="39">{{ chart(group).max }}</text><text x="2" y="134">{{ chart(group).min }}</text><polyline v-if="group.rows.length>1" :points="chart(group).points" fill="none" stroke="#288051" stroke-width="3"/><circle v-for="(point,i) in chart(group).points.split(' ')" :key="i" :cx="point.split(',')[0]" :cy="point.split(',')[1]" r="4" fill="#288051"/><text x="45" y="161">{{ time(group.rows[0].observedAt) }}</text><text x="335" y="174" text-anchor="end">{{ time(group.rows.at(-1).observedAt) }}</text></svg><details><summary>查看 {{ group.rows.length }} 条原始记录</summary><p>设备标识：{{ group.device }}</p><p v-for="row in group.rows" :key="row.id">{{ time(row.observedAt) }} · {{ row.value }} {{ row.unit || '单位未提供' }} · {{ row.quality }}</p></details></figure></div></details><div class="report-work-desktop"><h2>本次做了什么</h2><table><thead><tr><th>事项</th><th>截止时间</th><th>状态</th></tr></thead><tbody><tr v-for="task in doc.tasks" :key="task.id"><td>{{ task.title }}</td><td>{{ time(task.dueAt) }}</td><td>{{ statusLabel(task.status) }}</td></tr></tbody></table><p v-if="!doc.tasks.length">未选择任务</p></div><p v-for="(limit,i) in doc.limitations" :key="i" class="agri-notice">{{ readableLimit(limit) }}</p></template><template v-else><p class="agri-muted">历史正文报告 · 未附结构化监测数据</p><pre class="report-body">{{ report.body }}</pre></template><details><summary>依据与来源</summary><div v-for="(source,i) in sourceRows(doc?.sources || report.sources)" :key="i"><strong>{{ source.title }}</strong><p>{{ source.locator }} · {{ source.version }}</p><p>{{ source.excerpt }}</p></div></details><section v-if="pendingTasks.length"><h2>建议下一步</h2><div v-for="task in pendingTasks" :key="task.id"><p>{{ task.title }}</p><button @click="emit('next-step',task)">核对并安排下一步</button></div></section></article><div v-if="exportOpen" class="concept-export-backdrop"><section class="concept-export-sheet" role="dialog" aria-modal="true" aria-label="导出这份报告"><button :disabled="busy" @click="exportOpen=false">关闭</button><h2>导出这份报告</h2><p>导出内容与当前报告一致。</p><div class="concept-export-format"><span class="concept-md-file" aria-hidden="true">.md</span><div><h3>Markdown 文档</h3><p>文字报告，便于阅读与继续编辑。</p><small>包含照片说明，不包含原图</small></div></div><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><button :disabled="busy" @click="emit('export','md')">{{ busy ? '正在保存…' : '保存到设备' }}</button></section></div></section></template>

<style src="./concept-report.css"></style>
